(409187, 35989, 11748, '<td valign="top">Nice submission! Good composition and detail.</td>', 'Nice submission! Good composition and detail.', '2003-09-03 23:45:12.000000', NULL, 1),
(409189, 35606, 8125, '<td valign="top">Now this was a good idea - made me laugh the hardest...  I wish I had thought of it!  :-)  <br/> <br/>The only thing distracting me is the ''moon''.  It''s not quite round, and I can see something below it.  Maybe those are clouds??</td>', 'Now this was a good idea - made me laugh the hardest...  I wish I had thought of it!  :-)   The only thing distracting me is the ''moon''.  It''s not quite round, and I can see something below it.  Maybe those are clouds??', '2003-09-03 23:45:28.000000', NULL, 1),
(409190, 35972, 9073, '<td valign="top">Your first shot hit bull. Your second missed. I''ll split the difference and give you a 5. Fair?</td>', 'Your first shot hit bull. Your second missed. I''ll split the difference and give you a 5. Fair?', '2003-09-03 23:45:52.000000', NULL, 1),
