(409195, 36224, 8125, '<td valign="top">Hate it when that happens!  I might like to see this photo color...</td>', 'Hate it when that happens!  I might like to see this photo color...', '2003-09-03 23:48:50.000000', NULL, 1),
(409196, 35770, 9073, '<td valign="top">Funny</td>', 'Funny', '2003-09-03 23:48:56.000000', NULL, 1),
