(409199, 35870, 9073, '<td valign="top">Funny and cute.</td>', 'Funny and cute.', '2003-09-03 23:49:51.000000', NULL, 1),
(409201, 35400, 9073, '<td valign="top">A little longer shutter speed would have helped to catch the motion more which would have helped here a lot.</td>', 'A little longer shutter speed would have helped to catch the motion more which would have helped here a lot.', '2003-09-03 23:51:46.000000', NULL, 1),
(409202, 36181, 11748, '<td valign="top">wow, what detail. this really captures the challenge. great job!</td>', 'wow, what detail. this really captures the challenge. great job!', '2003-09-03 23:52:03.000000', NULL, 1),
(409204, 36084, 11748, '<td valign="top">Good concept and execution.</td>', 'Good concept and execution.', '2003-09-03 23:53:06.000000', NULL, 1),
(409205, 35847, 8125, '<td valign="top">Good idea - I like the way you''ve laid it all out.  There is a glare on the box distracting me, but otherwise well photographed.</td>', 'Good idea - I like the way you''ve laid it all out.  There is a glare on the box distracting me, but otherwise well photographed.', '2003-09-03 23:53:27.000000', NULL, 1),
(409206, 36254, 10799, '<td valign="top">My Grandmother actually put Brill Cream on my toothbrush when I was a little girl. I kept brushing my teeth and telling her that it disappeared.  She put more on my brush three times before she got her glasses and fixed her mistake.  You did a good job on this.  I should have thought of it!</td>', 'My Grandmother actually put Brill Cream on my toothbrush when I was a little girl. I kept brushing my teeth and telling her that it disappeared.  She put more on my brush three times before she got her glasses and fixed her mistake.  You did a good job on this.  I should have thought of it!', '2003-09-03 23:54:46.000000', NULL, 1),
(409207, 36143, 11073, '<td valign="top">=`)  This one hits home with me...that''s how i ended up with my canon that i have now.  I bought  a sony from circuit city...got back to the office and opened it...and...there were two disposable 35mm camera''s in the box!  Took it back, yelled a little and got a more expensive camera!  Good idea and shot.  The lighting up top is a little harsh imo.</td>', '=`)  This one hits home with me...that''s how i ended up with my canon that i have now.  I bought  a sony from circuit city...got back to the office and opened it...and...there were two disposable 35mm camera''s in the box!  Took it back, yelled a little and got a more expensive camera!  Good idea and shot.  The lighting up top is a little harsh imo.', '2003-09-03 23:55:28.000000', NULL, 1),
(409209, 35806, 8125, '<td valign="top">I rated this one a 7, mainly because it takes guts to take a shot like this!  :-)</td>', 'I rated this one a 7, mainly because it takes guts to take a shot like this!  :-)', '2003-09-03 23:58:10.000000', NULL, 1),
(409210, 35504, 11748, '<td valign="top">Good DOF and composition.</td>', 'Good DOF and composition.', '2003-09-03 23:58:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(409214, 36197, 10799, '<td valign="top">I keep coming back to this to find the opps.... Sorry, but I can''t find it.  Maybe I don''t know enough about building... blue ropes??? I don''t know <br/>The picture is a bit unclear and dull looking.  I don''t know what it needs.  Saturation or contrast?</td>', 'I keep coming back to this to find the opps.... Sorry, but I can''t find it.  Maybe I don''t know enough about building... blue ropes??? I don''t know The picture is a bit unclear and dull looking.  I don''t know what it needs.  Saturation or contrast?', '2003-09-04 00:01:51.000000', NULL, 1),
(409215, 36149, 8125, '<td valign="top">I''m curious where you got the tooth from. :-)  <br/> <br/>The ''blood'' looks a lot like ketchup.  A tooth would have bent the cap at the edge instead of a straight line down the center.  (Not that I know from experience!)  :-)  <br/> <br/>Good idea though!</td>', 'I''m curious where you got the tooth from. :-)   The ''blood'' looks a lot like ketchup.  A tooth would have bent the cap at the edge instead of a straight line down the center.  (Not that I know from experience!)  :-)   Good idea though!', '2003-09-04 00:02:17.000000', NULL, 1),
(409222, 35473, 11748, '<td valign="top">I like the idea and the expression in the eyes. I wish that the color on the hair was more vibrant.</td>', 'I like the idea and the expression in the eyes. I wish that the color on the hair was more vibrant.', '2003-09-04 00:05:02.000000', NULL, 1),
(409223, 36039, 11034, '<td valign="top">A little bit out of focus but good idea.</td>', 'A little bit out of focus but good idea.', '2003-09-04 00:05:31.000000', NULL, 1),
(409226, 35879, 8125, '<td valign="top">Interesting the way the tree branches are wrapping around the brick left standing</td>', 'Interesting the way the tree branches are wrapping around the brick left standing', '2003-09-04 00:08:32.000000', NULL, 1),
(409227, 35848, 8125, '<td valign="top">I''m not seeing the oops....</td>', 'I''m not seeing the oops....', '2003-09-04 00:10:04.000000', NULL, 1),
(409230, 36222, 9073, '<td valign="top">I like this one. Conceptually, funny. Photographically, colours spot on, focus crisp, composition balanced, backing even. Nicely done.</td>', 'I like this one. Conceptually, funny. Photographically, colours spot on, focus crisp, composition balanced, backing even. Nicely done.', '2003-09-04 00:12:24.000000', NULL, 1),
