(409255, 36066, 6668, '<td valign="top">Great picture...good job!</td>', 'Great picture...good job!', '2003-09-04 00:36:22.000000', NULL, 1),
(409256, 35499, 6668, '<td valign="top">Absolutely Adorable!</td>', 'Absolutely Adorable!', '2003-09-04 00:37:31.000000', NULL, 1),
(409266, 35847, 8624, '<td valign="top">good idea but it''s too cluttered. I don''t think you needed all the instruction text in the shot</td>', 'good idea but it''s too cluttered. I don''t think you needed all the instruction text in the shot', '2003-09-04 00:50:12.000000', NULL, 1),
(409268, 35506, 8624, '<td valign="top">fun idea but too cluttered. I like all the conversing lines of the building and the way the pole crosses over diagonally. The sky is way overexposed.</td>', 'fun idea but too cluttered. I like all the conversing lines of the building and the way the pole crosses over diagonally. The sky is way overexposed.', '2003-09-04 00:54:40.000000', NULL, 1),
(409271, 35752, 8624, '<td valign="top">good idea for the theme, but your execution doesn''t appear to be anything more than the hammer resting on the thumb. I don''t get a sense of you missing the nail and striking the thumb.</td>', 'good idea for the theme, but your execution doesn''t appear to be anything more than the hammer resting on the thumb. I don''t get a sense of you missing the nail and striking the thumb.', '2003-09-04 00:56:33.000000', NULL, 1),
(409274, 35812, 10319, '<td valign="top">Not only is the idea great, but so well executed... I really love the exagerated "feel" to this, as well as the great exposure</td>', 'Not only is the idea great, but so well executed... I really love the exagerated "feel" to this, as well as the great exposure', '2003-09-04 00:59:15.000000', NULL, 1),
(409275, 36065, 9643, '<td valign="top">I like the composition of this shot very much but it seems grainy.  On purpose?</td>', 'I like the composition of this shot very much but it seems grainy.  On purpose?', '2003-09-04 01:00:49.000000', NULL, 1),
(409277, 35795, 8624, '<td valign="top">this doesn''t look like there is an "oops" about to happen. he looks pretty competant in this shot.</td>', 'this doesn''t look like there is an "oops" about to happen. he looks pretty competant in this shot.', '2003-09-04 01:02:26.000000', NULL, 1),
(409279, 36085, 9643, '<td valign="top">What a nice candid.  I love the expressions on their faces and the fact that you caught 3 (and 1/2) giraffes in the picture.</td>', 'What a nice candid.  I love the expressions on their faces and the fact that you caught 3 (and 1/2) giraffes in the picture.', '2003-09-04 01:03:27.000000', NULL, 1),
(409280, 36143, 10319, '<td valign="top">lol!! This is clever!!</td>', 'lol!! This is clever!!', '2003-09-04 01:03:29.000000', NULL, 1),
(409283, 36041, 10084, '<td valign="top">Composition is great. Very funny expressions. Just wondering who did the submission. Tint is good.  Nice shadows. \"10\"  Are you going to share the Blue Ribbon when you win.</td>', 'Composition is great. Very funny expressions. Just wondering who did the submission. Tint is good.  Nice shadows. \"10\"  Are you going to share the Blue Ribbon when you win.', '2003-09-04 01:07:04.000000', NULL, 1),
(409286, 35862, 10084, '<td valign="top">Framing of composition is distracting. Wished you would''ve included more of the floor to frame the picture. Otherwise a very humorous shot with a great expression on the babies face. Lighting is good as well. "9"</td>', 'Framing of composition is distracting. Wished you would''ve included more of the floor to frame the picture. Otherwise a very humorous shot with a great expression on the babies face. Lighting is good as well. "9"', '2003-09-04 01:08:57.000000', NULL, 1),
(409287, 35620, 10084, '<td valign="top">Great composition. Beautiful shot. Love that you were able to capture the movement of the left foot stepping on the shoe lace. "9"</td>', 'Great composition. Beautiful shot. Love that you were able to capture the movement of the left foot stepping on the shoe lace. "9"', '2003-09-04 01:10:08.000000', NULL, 1),
(409288, 36066, 10084, '<td valign="top">Really good composition. Desaturation effect works very well in this shot. Great focus on the face.</td>', 'Really good composition. Desaturation effect works very well in this shot. Great focus on the face.', '2003-09-04 01:11:23.000000', NULL, 1),
(409290, 36186, 10084, '<td valign="top">Composition is very interesting. The angle you chose is good. Spotlighting for the leg is nice. Funny stuff.</td>', 'Composition is very interesting. The angle you chose is good. Spotlighting for the leg is nice. Funny stuff.', '2003-09-04 01:12:46.000000', NULL, 1),
(409292, 36149, 10084, '<td valign="top">Really nice colors.Is that ketchup? Depth of field is excellent. Sharpness of the reflections are very appealing. Not to thrilled about the frame colors.</td>', 'Really nice colors.Is that ketchup? Depth of field is excellent. Sharpness of the reflections are very appealing. Not to thrilled about the frame colors.', '2003-09-04 01:14:45.000000', NULL, 1),
(409293, 35791, 8624, '<td valign="top">cool idea, but bad shadows and a boring background hurt this shot. You should consider a simpler setup to highlight the cream and coffee cup.</td>', 'cool idea, but bad shadows and a boring background hurt this shot. You should consider a simpler setup to highlight the cream and coffee cup.', '2003-09-04 01:15:18.000000', NULL, 1),
(409295, 36254, 8624, '<td valign="top">good idea. I think a darker background would have set off the tube and brush better, though.</td>', 'good idea. I think a darker background would have set off the tube and brush better, though.', '2003-09-04 01:17:43.000000', NULL, 1),
