(409298, 36186, 9643, '<td valign="top">Really nice angle.</td>', 'Really nice angle.', '2003-09-04 01:20:29.000000', NULL, 1),
(409299, 35897, 9906, '<td valign="top">Is this your work???  (the drawing that is...)  If there is one thing I''ve always wished I could do (besides taking pictures) it would be drawing.....</td>', 'Is this your work???  (the drawing that is...)  If there is one thing I''ve always wished I could do (besides taking pictures) it would be drawing.....', '2003-09-04 01:22:07.000000', NULL, 1),
