(409484, 36034, 11073, '<td valign="top">ahhh, equal opportunity employment.  Ain''t it grand?  Cool shot.</td>', 'ahhh, equal opportunity employment.  Ain''t it grand?  Cool shot.', '2003-09-04 05:04:13.000000', NULL, 1),
(409486, 36202, 11073, '<td valign="top">Ahhhh.  Todays male is becoming too sensitive and less manly every year.  Tell her that you ripped the tape on purpose - because you wanted to - and that there is no such thing as "doghouse" in the house that you paid for (or at least half -and that means half the master bed too...).  But I digress on the "femification" of todays male.....The composition is nice, the dof if good.  The lighting is good too.</td>', 'Ahhhh.  Todays male is becoming too sensitive and less manly every year.  Tell her that you ripped the tape on purpose - because you wanted to - and that there is no such thing as "doghouse" in the house that you paid for (or at least half -and that means half the master bed too...).  But I digress on the "femification" of todays male.....The composition is nice, the dof if good.  The lighting is good too.', '2003-09-04 05:10:37.000000', NULL, 1),
(409492, 36228, 10869, '<td valign="top">those big bubbles are bit too distracting</td>', 'those big bubbles are bit too distracting', '2003-09-04 05:25:28.000000', NULL, 1),
