(409495, 35432, 10869, '<td valign="top">lightning may have been better</td>', 'lightning may have been better', '2003-09-04 05:31:50.000000', NULL, 1),
(409497, 35531, 10869, '<td valign="top">really bad picture quality</td>', 'really bad picture quality', '2003-09-04 05:33:18.000000', NULL, 1),
